    },
    {
      "indicator": "MM50",
      "reading": "R$18,4090",
      "interpretation": "Média de médio prazo acima do preço — mantém tendência de baixa estrutural."
    },
    {
      "indicator": "MM200",
      "reading": "R$20,5957",
      "interpretation": "Média de longo prazo bem acima do preço; tendência de longo prazo ainda negativa."
    },
    {
      "indicator": "EMA9",
      "reading": "R$16,9267",
      "interpretation": "EMA rápida abaixo da EMA21 e acima do preço — pressão vendedora de curto prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "R$17,3417",
      "interpretation": "EMA de referência de curto/médio prazo atuando como resistência dinâmica."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD -0,4845 / sinal -0,4870 / hist +0,0025",
      "interpretation": "MACD negativo indica momentum baixista; histograma muito pequeno sinaliza leve convergência, sem confirmação de reversão."
    },
    {
      "indicator": "Bollinger (20,2σ)",
      "reading": "lower 16.2281 / mid 17.3745 / upper 18.5209",
      "interpretation": "Preço próximo da banda inferior — curto prazo sobrevendido e possível repique técnico; banda média descendente confirma tendência de baixa."
    },
    {
      "indicator": "RSI (14)",
      "reading": "31.5138",
      "interpretation": "Próximo de sobrevenda (30). Pode favorecer repique corretivo, mas não mostra divergência positiva clara."
    },
    {
      "indicator": "Volume",
      "reading": "3.218.895.900",
      "interpretation": "Volume do pregão final moderado; quedas anteriores com volume elevado confirmaram pressão vendedora. Ausência de volume comprador robusto que valide reversão."
    }
  ]
